// 由 scripts/build.js 生成，不要手改；改 web/ 下的文件后重新运行 node scripts/build.js
export const HTML: string = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"apple-mobile-web-app-title\" content=\"早饭\">\n<meta name=\"theme-color\" content=\"#ffcf4d\">\n<title>早饭</title>\n<link rel=\"manifest\" href=\"manifest.webmanifest\">\n<link rel=\"apple-touch-icon\" href=\"icon.png\">\n<link rel=\"icon\" href=\"icon.png\">\n<script>(function(){var b=location.pathname.replace(/\\/+$/,\"\");document.querySelectorAll(\"link[rel=manifest],link[rel=apple-touch-icon],link[rel=icon]\").forEach(function(l){l.href=b+\"/\"+l.getAttribute(\"href\");});})();</script>\n<style>\n/* 老人优先：浅底、深字、超大字、超大按钮、一屏只放一件事 */\n:root{--bg:#fff8e7;--paper:#fff;--fg:#1f1b17;--muted:#6f655a;--line:#eadcb8;--accent:#ffcf4d;--accent-deep:#f0b000;--pick:#ff8c00;--pick-soft:#fff0d2;--good:#1b7a2a;--bad:#c62828;--bad-soft:#ffe3e3;--soft:#ffe9a8}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;background:var(--bg);color:var(--fg);font-family:-apple-system,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",\"Noto Sans CJK SC\",sans-serif;font-size:20px;line-height:1.3}\nbody{padding:env(safe-area-inset-top) max(14px,env(safe-area-inset-right)) calc(24px + env(safe-area-inset-bottom)) max(14px,env(safe-area-inset-left));max-width:720px;margin:0 auto;min-height:100vh}\nbutton,input{font:inherit;color:inherit}\nbutton{cursor:pointer}\nbutton:disabled{opacity:.45;cursor:default}\nheader{text-align:center;padding:12px 0 2px}\nheader h1{font-size:38px;margin:0}\nheader p{font-size:20px;color:var(--muted);margin:4px 0 0;min-height:1.3em}\nnav{display:flex;gap:10px;position:sticky;top:env(safe-area-inset-top);background:var(--bg);z-index:5;padding:10px 0}\nnav button{flex:1;min-width:0;font-size:26px;font-weight:700;padding:16px 4px;border:3px solid var(--accent-deep);border-radius:18px;background:var(--paper)}\nnav button.active{background:var(--accent)}\n.view{display:none;padding-top:8px}.view.active{display:block}\n.hint{font-size:22px;color:var(--muted);text-align:center;margin:6px 0 14px}\n.note{font-size:19px;color:var(--muted);text-align:center;margin:10px 0}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px}\n.card{min-width:0;overflow:hidden;background:var(--paper);border:4px solid var(--line);border-radius:22px;padding:0;text-align:center;display:flex;flex-direction:column}\n.card.selected{border-color:var(--pick);background:var(--pick-soft)}\n.pic{position:relative;height:150px;background:var(--soft);display:flex;align-items:center;justify-content:center;overflow:hidden}\n.pic .emoji{font-size:80px;line-height:1}\n.pic img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity .25s}\n.pic img.ok{opacity:1}\n.card .name{font-size:28px;font-weight:700;padding:10px 6px 12px;overflow-wrap:anywhere;line-height:1.2}\n.card .tick{font-size:19px;color:var(--pick);font-weight:700;padding-bottom:10px;margin-top:-6px}\n.special{display:flex;gap:12px;margin-top:16px}\n.big-btn{font-size:28px;font-weight:700;padding:20px 16px;border-radius:20px;border:3px solid var(--accent-deep);background:var(--paper);flex:1;min-width:0}\n#btnRandom{background:var(--accent)}\n#btnSkip{background:var(--bad-soft);border-color:var(--bad)}\n.status{font-size:24px;text-align:center;color:var(--good);min-height:1.4em;margin:14px 0 0;font-weight:700}\n.morning-card{background:var(--paper);border-radius:28px;overflow:hidden;text-align:center;margin-bottom:16px;border:4px solid var(--line)}\n.morning-card .pic{height:auto;aspect-ratio:4/3;max-height:46vh}\n.morning-card .pic .emoji{font-size:150px}\n.morning-card .name{font-size:64px;font-weight:800;padding:20px 10px 6px;overflow-wrap:anywhere;line-height:1.1}\n.morning-card .sub{font-size:26px;color:var(--muted);padding:0 12px 22px}\n#btnSpeak{width:100%;background:var(--accent);font-size:32px;padding:24px}\n.add-row{display:flex;gap:8px}\n.add-row input{flex:1;min-width:0;font-size:24px;padding:14px;border-radius:16px;border:3px solid var(--line);background:var(--paper)}\n#btnVoice{width:100%;margin-top:10px;background:#e8f5e9;border-color:#7cb97f}\n#btnVoice.listening{background:var(--pick-soft);border-color:var(--pick)}\n.menu-list{list-style:none;padding:0;margin:16px 0 0}\n.menu-list li{display:flex;align-items:center;gap:10px;background:var(--paper);border:3px solid var(--line);border-radius:18px;padding:10px;margin-bottom:10px;min-width:0;flex-wrap:wrap}\n.menu-list .thumb{width:76px;height:76px;border-radius:14px;flex-shrink:0;background:var(--soft);display:flex;align-items:center;justify-content:center;font-size:44px;overflow:hidden;position:relative}\n.menu-list .thumb img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0}\n.menu-list .thumb img.ok{opacity:1}\n.menu-list .mname{flex:1;min-width:110px;font-size:28px;font-weight:700;overflow-wrap:anywhere}\n.acts{display:flex;gap:6px;flex-shrink:0;flex-wrap:wrap}\n.acts button,.acts label{font-size:24px;padding:12px 14px;border-radius:14px;border:2px solid var(--line);background:var(--bg);display:inline-block;cursor:pointer}\n.acts .del{color:var(--bad)}\n.acts .del.confirm{background:var(--bad);border-color:var(--bad);color:#fff}\n.acts input[type=file]{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}\n.empty{background:var(--paper);border:3px dashed var(--line);border-radius:22px;padding:28px 16px;text-align:center;font-size:22px;color:var(--muted);grid-column:1/-1}\n.toast{position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom));transform:translateX(-50%);background:#1f1b17;color:#fff;padding:14px 22px;border-radius:16px;font-size:22px;z-index:20;max-width:90vw;text-align:center}\n.foot{text-align:center;margin-top:28px;font-size:18px;color:var(--muted)}\n.foot button{background:none;border:none;text-decoration:underline;color:var(--muted);font-size:18px;padding:8px}\n/* 第一次打开：选我是谁 */\n#who{text-align:center;padding:30px 0}\n#who h2{font-size:34px;margin:0 0 8px}\n#who p{font-size:22px;color:var(--muted);margin:0 0 24px}\n#who button{display:block;width:100%;font-size:40px;font-weight:800;padding:34px 20px;border-radius:26px;border:4px solid var(--accent-deep);background:var(--paper);margin-bottom:16px}\n#who button.mom{background:var(--accent)}\n/* 妈妈模式：字再大一号，少一个页签 */\nbody.mom{font-size:22px}\nbody.mom nav button{font-size:30px;padding:20px 4px}\nbody.mom .morning-card .name{font-size:76px}\nbody.mom .morning-card .sub{font-size:30px}\nbody.mom #btnSpeak{font-size:36px;padding:28px}\nbody.mom .menu-list .mname,body.mom .card .name{font-size:30px}\n@media (prefers-reduced-motion:no-preference){.card:active,.big-btn:active,nav button:active{transform:scale(.97)}}\n</style>\n</head>\n<body>\n<header><h1>🍜 早饭</h1><p id=\"dateLine\"></p></header>\n\n<section id=\"who\" hidden>\n  <h2>这是谁的手机？</h2>\n  <p>选一次就记住了，以后不再问</p>\n  <button type=\"button\" class=\"mom\" data-role=\"mom\">👩 我是妈妈</button>\n  <button type=\"button\" data-role=\"kid\">👧 我是女儿</button>\n</section>\n\n<div id=\"app\" hidden>\n<nav>\n  <button type=\"button\" data-view=\"pick\">选早饭</button>\n  <button type=\"button\" data-view=\"morning\">今天早上</button>\n  <button type=\"button\" data-view=\"menu\">菜单</button>\n</nav>\n\n<section id=\"view-pick\" class=\"view\">\n  <p class=\"hint\">点一张图片就选好啦</p>\n  <div id=\"pickGrid\" class=\"grid\"></div>\n  <div class=\"special\">\n    <button type=\"button\" id=\"btnRandom\" class=\"big-btn\">随便</button>\n    <button type=\"button\" id=\"btnSkip\" class=\"big-btn\">今天不吃</button>\n  </div>\n  <p id=\"pickStatus\" class=\"status\"></p>\n</section>\n\n<section id=\"view-morning\" class=\"view\">\n  <div id=\"morningCard\" class=\"morning-card\"></div>\n  <button type=\"button\" id=\"btnSpeak\" class=\"big-btn\">🔊 读给我听</button>\n  <p id=\"speakNote\" class=\"note\"></p>\n</section>\n\n<section id=\"view-menu\" class=\"view\">\n  <p class=\"hint\">加新菜、拍张照片、删除、上下移动</p>\n  <form class=\"add-row\" id=\"addForm\">\n    <input id=\"newDishName\" placeholder=\"输入菜名，比如：三文鱼吐司\" autocomplete=\"off\">\n    <button type=\"submit\" id=\"btnAdd\" class=\"big-btn\" style=\"flex:0 0 auto\">加菜</button>\n  </form>\n  <button type=\"button\" id=\"btnVoice\" class=\"big-btn\">🎤 语音加菜</button>\n  <p id=\"voiceStatus\" class=\"note\"></p>\n  <ul id=\"menuList\" class=\"menu-list\"></ul>\n</section>\n\n<p id=\"syncNote\" class=\"note\"></p>\n<p class=\"foot\"><span id=\"roleLine\"></span> <button type=\"button\" id=\"btnSwitchRole\">换个人</button></p>\n</div>\n\n<script>\n(function(){\n'use strict';\nvar BASE = location.pathname.replace(/\\/+$/, '');\nvar FALLBACK_NAME = '鸡蛋三明治', FALLBACK_EMOJI = '🥪';\nvar EMOJI_RULES = [['三明治','🥪'],['汉堡','🍔'],['吐司','🍞'],['面包','🍞'],['馒头','🍞'],['花卷','🍞'],['馄饨','🥟'],['云吞','🥟'],['饺','🥟'],['包子','🥟'],['小笼','🥟'],['烧卖','🥟'],['炒饭','🍚'],['米饭','🍚'],['饭团','🍙'],['粥','🥣'],['麦片','🥣'],['燕麦','🥣'],['意面','🍝'],['荞麦','🍝'],['面','🍜'],['粉','🍜'],['蛋','🥚'],['煎饼','🥞'],['饼','🥞'],['华夫','🧇'],['牛奶','🥛'],['豆浆','🥛'],['酸奶','🥛'],['油条','🥖'],['香蕉','🍌'],['苹果','🍎'],['水果','🍎'],['汤','🍲'],['火腿','🥓'],['培根','🥓'],['香肠','🌭'],['红薯','🍠'],['玉米','🌽']];\nfunction emojiFor(name){ for (var i=0;i<EMOJI_RULES.length;i++){ if (name.indexOf(EMOJI_RULES[i][0])>=0) return EMOJI_RULES[i][1]; } return '🍽️'; }\n\nvar state = { dishes: [], pick: null, pickDate: null };\nvar loaded = false, role = null, pendingDelete = null, lastOk = 0;\nfunction $(id){ return document.getElementById(id); }\nfunction esc(s){ return String(s).replace(/[&<>\"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]; }); }\nvar toastTimer;\nfunction toast(msg){ var t=document.querySelector('.toast'); if(!t){ t=document.createElement('div'); t.className='toast'; document.body.appendChild(t);} t.textContent=msg; t.hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(function(){ t.hidden=true; },2600); }\nfunction store(k,v){ try{ if(v===null) localStorage.removeItem(k); else localStorage.setItem(k,v);}catch(e){} }\nfunction load(k){ try{ return localStorage.getItem(k);}catch(e){ return null; } }\n\nfunction pad(n){ return (n<10?'0':'')+n; }\nfunction localDate(d){ return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()); }\nfunction targetDate(){ var now=new Date(), d=new Date(now); if(now.getHours()>=15) d.setDate(d.getDate()+1); return localDate(d); }\nfunction dateLabel(ds){\n  var p=ds.split('-').map(Number), dd=new Date(p[0],p[1]-1,p[2]), w='日一二三四五六';\n  var base=p[1]+'月'+p[2]+'日 周'+w[dd.getDay()], t=new Date(); t.setDate(t.getDate()+1);\n  if (ds===localDate(new Date())) return '今天 '+base; if (ds===localDate(t)) return '明天 '+base; return base;\n}\nfunction pickIsCurrent(){ return state.pick && state.pickDate===targetDate(); }\nfunction picHtml(d){\n  var em = '<span class=\"emoji\" aria-hidden=\"true\">'+esc(d.emoji||emojiFor(d.name))+'</span>';\n  var img = d.image ? '<img src=\"'+esc(d.image)+'\" alt=\"\" loading=\"lazy\" onload=\"this.className=\\'ok\\'\" onerror=\"this.remove()\">' : '';\n  return '<div class=\"pic\">'+em+img+'</div>';\n}\n\n// ---- 网络 ----\nfunction api(path, opts){\n  opts = opts || {};\n  var o = { method: opts.method||'GET', headers: {} };\n  if (opts.json){ o.headers['Content-Type']='application/json'; o.body=JSON.stringify(opts.json); }\n  if (opts.blob){ o.headers['Content-Type']=opts.blob.type||'image/jpeg'; o.body=opts.blob; }\n  return fetch(BASE+path, o).then(function(r){\n    return r.json().catch(function(){ return {}; }).then(function(j){ if(!r.ok) throw new Error(j.error||('出错了 '+r.status)); return j; });\n  });\n}\nfunction loadState(){\n  return api('/api/state').then(function(s){ state=s; loaded=true; lastOk=Date.now(); $('syncNote').textContent=''; render(); })\n    .catch(function(){ if(!loaded) $('syncNote').textContent='连不上网，正在重试…'; else if(Date.now()-lastOk>60000) $('syncNote').textContent='网络不太好，显示的可能不是最新的'; render(); });\n}\nfunction act(p){ return p.then(loadState).catch(function(e){ toast(e.message||'没成功，请再试一次'); }); }\n\n// ---- 渲染 ----\nfunction render(){\n  var td=targetDate(), cur=pickIsCurrent()?state.pick:null, list=state.dishes||[];\n  $('dateLine').textContent = '选的是 '+dateLabel(td)+' 的早饭';\n\n  var grid=$('pickGrid');\n  if(!loaded) grid.innerHTML='<div class=\"empty\">正在打开菜单…</div>';\n  else if(!list.length) grid.innerHTML='<div class=\"empty\">菜单还是空的，到「菜单」页加第一道菜吧。</div>';\n  else grid.innerHTML=list.map(function(d){ var sel=cur&&cur.dish===d.id; return '<button type=\"button\" class=\"card'+(sel?' selected':'')+'\" data-name=\"'+esc(d.name)+'\">'+picHtml(d)+'<div class=\"name\">'+esc(d.name)+'</div>'+(sel?'<div class=\"tick\">✓ 就吃这个</div>':'')+'</button>'; }).join('');\n  Array.prototype.forEach.call(grid.querySelectorAll('.card'), function(el){ el.onclick=function(){ act(api('/api/pick',{method:'POST',json:{type:el.getAttribute('data-name'),date:td}}).then(function(){ toast('选好了：'+el.getAttribute('data-name')); })); }; });\n  $('pickStatus').textContent = cur ? (cur.type==='skip'?'已选好：今天不吃':'已选好：'+cur.resolvedName+(cur.type==='random'?'（随便选的）':'')) : (loaded?'还没选，不选就是'+FALLBACK_NAME:'');\n  $('btnRandom').disabled=!list.length;\n\n  var mc=$('morningCard'), name, sub, body;\n  if(cur&&cur.type==='skip'){ name='今天不吃'; sub='不用做'; body='<div class=\"pic\"><span class=\"emoji\">😴</span></div>'; }\n  else if(cur){ var d=null; for(var i=0;i<list.length;i++) if(list[i].id===cur.dish) d=list[i]; name=cur.resolvedName; sub=cur.type==='random'?'随便选的，就它了':'女儿选的'; body=d?picHtml(d):'<div class=\"pic\"><span class=\"emoji\">'+emojiFor(name)+'</span></div>'; }\n  else { name=FALLBACK_NAME; sub=loaded?'没选，就做这个':'正在连接…'; body='<div class=\"pic\"><span class=\"emoji\">'+FALLBACK_EMOJI+'</span></div>'; }\n  mc.innerHTML=body+'<div class=\"name\">'+esc(name)+'</div>'+(sub?'<div class=\"sub\">'+esc(sub)+'</div>':'');\n  mc.setAttribute('data-speak', name==='今天不吃'?'今天不吃早饭，不用做':'今天早饭是'+name);\n\n  var ml=$('menuList');\n  if(!loaded) ml.innerHTML='';\n  else if(!list.length) ml.innerHTML='<li class=\"empty\" style=\"display:block\">还没有菜。在上面输入菜名，点「加菜」。</li>';\n  else ml.innerHTML=list.map(function(d,i){\n    var th='<div class=\"thumb\">'+esc(d.emoji||emojiFor(d.name))+(d.image?'<img src=\"'+esc(d.image)+'\" alt=\"\" onload=\"this.className=\\'ok\\'\" onerror=\"this.remove()\">':'')+'</div>';\n    return '<li><div class=\"thumb-wrap\">'+th+'</div><span class=\"mname\">'+esc(d.name)+'</span><div class=\"acts\">'\n      +'<label title=\"拍照或选图\">📷<input type=\"file\" accept=\"image/*\" data-id=\"'+d.id+'\"></label>'\n      +'<button type=\"button\" data-act=\"up\" data-id=\"'+d.id+'\" '+(i===0?'disabled':'')+' aria-label=\"上移\">↑</button>'\n      +'<button type=\"button\" data-act=\"down\" data-id=\"'+d.id+'\" '+(i===list.length-1?'disabled':'')+' aria-label=\"下移\">↓</button>'\n      +'<button type=\"button\" class=\"del'+(pendingDelete===d.id?' confirm':'')+'\" data-act=\"del\" data-id=\"'+d.id+'\">'+(pendingDelete===d.id?'确定删除？':'删除')+'</button></div></li>';\n  }).join('');\n  Array.prototype.forEach.call(ml.querySelectorAll('button'), function(b){ b.onclick=function(){ menuAction(b.getAttribute('data-act'), Number(b.getAttribute('data-id'))); }; });\n  Array.prototype.forEach.call(ml.querySelectorAll('input[type=file]'), function(inp){ inp.onchange=function(){ if(inp.files[0]) uploadPhoto(Number(inp.getAttribute('data-id')), inp.files[0]); }; });\n}\n\nfunction menuAction(a, id){\n  if(a==='del'){\n    if(pendingDelete!==id){ pendingDelete=id; render(); setTimeout(function(){ if(pendingDelete===id){ pendingDelete=null; render(); } },4000); return; }\n    pendingDelete=null; return act(api('/api/dishes/'+id,{method:'DELETE'}).then(function(){ toast('删掉了'); }));\n  }\n  return act(api('/api/dishes/'+id+'/move',{method:'POST',json:{direction:a}}));\n}\nfunction shrink(file){\n  return new Promise(function(res){\n    var img=new Image(), url=URL.createObjectURL(file);\n    img.onload=function(){ var s=Math.min(1,1200/Math.max(img.width,img.height)); var c=document.createElement('canvas'); c.width=Math.round(img.width*s); c.height=Math.round(img.height*s); c.getContext('2d').drawImage(img,0,0,c.width,c.height); URL.revokeObjectURL(url); c.toBlob(function(b){ res(b||file); },'image/jpeg',0.85); };\n    img.onerror=function(){ URL.revokeObjectURL(url); res(file); };\n    img.src=url;\n  });\n}\nfunction uploadPhoto(id, file){\n  toast('正在上传照片…');\n  shrink(file).then(function(blob){ return api('/api/dishes/'+id+'/photo',{method:'POST',blob:blob}); })\n    .then(function(){ toast('照片换好了'); return loadState(); })\n    .catch(function(e){ toast(e.message||'照片没传上'); });\n}\n$('btnRandom').onclick=function(){ act(api('/api/pick',{method:'POST',json:{type:'random',date:targetDate()}}).then(function(r){ toast('随便选了：'+r.pick.resolvedName); })); };\n$('btnSkip').onclick=function(){ act(api('/api/pick',{method:'POST',json:{type:'skip',date:targetDate()}}).then(function(){ toast('好，今天不吃'); })); };\n$('addForm').onsubmit=function(e){ e.preventDefault(); var inp=$('newDishName'), name=inp.value.trim(); if(!name) return; act(api('/api/dishes',{method:'POST',json:{name:name}}).then(function(){ toast('已加上：'+name); inp.value=''; })); };\n\n// ---- 朗读 ----\nfunction speak(text){\n  if(!('speechSynthesis' in window)){ $('speakNote').textContent='这个手机不能朗读，看上面的大字就好'; return; }\n  var u=new SpeechSynthesisUtterance(text); u.lang='zh-CN'; u.rate=0.85;\n  var vs=speechSynthesis.getVoices(); for(var i=0;i<vs.length;i++){ if(/^zh/i.test(vs[i].lang)){ u.voice=vs[i]; break; } }\n  speechSynthesis.cancel(); speechSynthesis.speak(u);\n}\n$('btnSpeak').onclick=function(){ speak($('morningCard').getAttribute('data-speak')||''); };\nif('speechSynthesis' in window) speechSynthesis.onvoiceschanged=function(){};\n\n// ---- 语音加菜 ----\nvar SR=window.SpeechRecognition||window.webkitSpeechRecognition;\nif(!SR) $('btnVoice').hidden=true;\nelse $('btnVoice').onclick=function(){\n  var vs=$('voiceStatus'), btn=$('btnVoice'), r=new SR(); r.lang='zh-CN'; r.interimResults=false; r.maxAlternatives=1;\n  vs.textContent='请说菜名…'; btn.classList.add('listening');\n  r.onresult=function(e){ var name=e.results[0][0].transcript.replace(/[。，,.!！?？\\s]+$/,'').trim(); vs.textContent='听到：'+name; act(api('/api/dishes',{method:'POST',json:{name:name}}).then(function(){ toast('已加上：'+name); })); };\n  r.onerror=function(e){ vs.textContent = e.error==='not-allowed' ? '没有麦克风权限，请打字加菜' : '没听清，请再说一次'; };\n  r.onend=function(){ btn.classList.remove('listening'); };\n  try{ r.start(); }catch(e){ vs.textContent='语音暂时用不了，请打字加菜'; btn.classList.remove('listening'); }\n};\n\n// ---- 角色与页面 ----\nvar VIEWS=['pick','morning','menu'];\nfunction showView(v){\n  if(VIEWS.indexOf(v)<0) v = role==='mom' ? 'morning' : (new Date().getHours()<15 ? 'morning' : 'pick');\n  VIEWS.forEach(function(x){ $('view-'+x).classList.toggle('active', x===v); });\n  Array.prototype.forEach.call(document.querySelectorAll('nav button'), function(b){ b.classList.toggle('active', b.getAttribute('data-view')===v); });\n}\nArray.prototype.forEach.call(document.querySelectorAll('nav button'), function(b){ b.onclick=function(){ showView(b.getAttribute('data-view')); }; });\nfunction applyRole(r){\n  role=r; document.body.classList.toggle('mom', r==='mom');\n  $('who').hidden=true; $('app').hidden=false;\n  document.querySelector('nav button[data-view=\"pick\"]').style.display = r==='mom' ? 'none' : '';\n  $('roleLine').textContent = r==='mom' ? '这是妈妈的手机' : '这是女儿的手机';\n  showView(null); render();\n}\nArray.prototype.forEach.call(document.querySelectorAll('#who button'), function(b){ b.onclick=function(){ var r=b.getAttribute('data-role'); store('bf_role', r); applyRole(r); }; });\n$('btnSwitchRole').onclick=function(){ store('bf_role', null); $('app').hidden=true; $('who').hidden=false; };\nvar saved=load('bf_role');\nif(saved==='mom'||saved==='kid') applyRole(saved); else $('who').hidden=false;\n\nloadState();\nsetInterval(loadState, 10000);\ndocument.addEventListener('visibilitychange', function(){ if(!document.hidden) loadState(); });\nwindow.addEventListener('online', loadState);\nsetInterval(render, 60000);\n})();\n</script>\n</body>\n</html>\n";
